<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { accionProceso, detalleProceso, guardarProceso, listarProcesos, type EtapaProceso, type ProcesoCompra, type ProcesoOptions } from '../services/procesosCompra'
const rows=ref<ProcesoCompra[]>([]),options=ref<ProcesoOptions>({estados:[],etapas:[],pedidos:[]}),total=ref(0),lastPage=ref(1),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),detail=ref<ProcesoCompra|null>(null),editing=ref<number|null>(null),pedidoSearch=ref('')
const filters=reactive({q:'',inicio_desde:'',fin_hasta:'',estado:'',etapa_vigente:'',page:1}),form=reactive({titulo:'',descripcion:'',tipo:'m' as 'a'|'m'|'s',registro:new Date().toISOString().slice(0,16),pedidos_relacionados:[] as number[],etapas:[] as EtapaProceso[]})
const availableOrders=computed(()=>options.value.pedidos.filter(x=>(!x.tipo||x.tipo===form.tipo)&&(!pedidoSearch.value||String(x.id).includes(pedidoSearch.value)||x.informacion?.toLowerCase().includes(pedidoSearch.value.toLowerCase()))))
async function load(page=1){filters.page=page;loading.value=true;error.value='';try{const response=await listarProcesos(filters);rows.value=response.data;total.value=response.total;lastPage.value=response.last_page;options.value=response.options}catch(cause){error.value=message(cause)}finally{loading.value=false}}
async function open(item?:ProcesoCompra){editing.value=item?.id||null;let current=item;if(item)try{current=await detalleProceso(item.id)}catch{}Object.assign(form,{titulo:current?.nombre||'',descripcion:current?.descripcion||'',tipo:current?.tipo||'m',registro:current?.registro||new Date().toISOString().slice(0,16),pedidos_relacionados:current?.pedidos?.map(x=>x.id)||[],etapas:current?.etapas?.map(x=>({...x}))||options.value.etapas.map((x,i)=>({id:x.id,nombre:x.nombre,fecha_inicio:'',fecha_fin:'',orden:i+1}))});modal.value=true}
function toggleOrder(id:number){form.pedidos_relacionados=form.pedidos_relacionados.includes(id)?form.pedidos_relacionados.filter(x=>x!==id):[...form.pedidos_relacionados,id]}
function move(index:number,direction:number){const next=index+direction;if(next<0||next>=form.etapas.length)return;[form.etapas[index],form.etapas[next]]=[form.etapas[next]!,form.etapas[index]!];form.etapas.forEach((x,i)=>x.orden=i+1)}
async function save(){if(!form.titulo.trim()){error.value='Ingrese el título del proceso.';return}if(!form.pedidos_relacionados.length){error.value='Seleccione al menos un pedido.';return}const stages=form.etapas.filter(x=>x.fecha_inicio);if(!stages.length){error.value='Configure al menos una etapa con fecha.';return}if(stages.some(x=>x.fecha_fin&&x.fecha_inicio!>x.fecha_fin)){error.value='La fecha final de una etapa no puede ser menor a la inicial.';return}saving.value=true;try{await guardarProceso(editing.value,{...form,etapas:stages.map(x=>({etapa_id:x.id,fecha_inicio:x.fecha_inicio,fecha_fin:x.fecha_fin||x.fecha_inicio}))});success.value='Proceso guardado correctamente.';modal.value=false;await load()}catch(cause){error.value=message(cause)}finally{saving.value=false}}
async function show(item:ProcesoCompra){try{detail.value=await detalleProceso(item.id)}catch(cause){error.value=message(cause)}}
async function action(item:ProcesoCompra,actionName:'publicar'|'siguiente-etapa'|'enviar-validacion'|'retornar-evaluacion'|'declarar-desierto'|'eliminar'){if(!confirm(`¿Confirmar la acción “${actionName.replaceAll('-',' ')}” para el proceso #${item.id}?`))return;try{await accionProceso(item.id,actionName);success.value='Estado del proceso actualizado correctamente.';detail.value=null;await load()}catch(cause){error.value=message(cause)}}
function message(cause:unknown){return cause instanceof Error?cause.message:'No se pudo completar la operación.'}onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Logística / Procesos de compra</nav><header class="hero"><div class="mark">PC</div><div><small>MIA · Logística</small><h1>Procesos de compra</h1><p>Administra pedidos asociados, cronograma, publicación y avance de etapas.</p></div><strong>{{total}} procesos</strong><button @click="open()">+ Nuevo proceso</button></header><p v-if="success" class="flash">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><section class="filters"><label>Proceso<input v-model.trim="filters.q" placeholder="Nombre o descripción" @keyup.enter="load(1)"></label><label>Inicio desde<input v-model="filters.inicio_desde" type="date"></label><label>Fin hasta<input v-model="filters.fin_hasta" type="date"></label><label>Estado<select v-model="filters.estado"><option value="">Todos</option><option v-for="state in options.estados" :key="state.id" :value="state.id">{{state.nombre}}</option></select></label><label>Etapa<select v-model="filters.etapa_vigente"><option value="">Todas</option><option v-for="stage in options.etapas" :key="stage.id" :value="stage.id">{{stage.nombre}}</option></select></label><button @click="load(1)">Buscar</button></section><div v-if="loading" class="empty">Cargando procesos…</div><div v-else-if="!rows.length" class="empty">No existen procesos registrados.</div><section v-else class="table"><header><span>Código</span><span>Nombre</span><span>Inicio</span><span>Fin</span><span>Estado</span><span>Etapa vigente</span><span>Postores</span><span>Acciones</span></header><article v-for="item in rows" :key="item.id"><b>#{{String(item.id).padStart(6,'0')}}</b><div><b>{{item.nombre}}</b><small>{{item.descripcion}}</small></div><time>{{item.inicio||'—'}}</time><time>{{item.fin||'—'}}</time><em>{{item.estado_nombre}}</em><span>{{item.etapa_nombre||'Sin etapa'}}</span><span>{{item.postores_count}}</span><footer><button @click="show(item)">Ver</button><button v-if="item.puede_editar" @click="open(item)">Editar</button><button v-if="item.puede_publicar" class="good" @click="action(item,'publicar')">Publicar</button><button v-if="item.puede_avanzar" class="good" @click="action(item,'siguiente-etapa')">Avanzar</button><button v-if="item.puede_enviar_validacion" @click="action(item,'enviar-validacion')">Validación</button><button v-if="item.puede_declarar_desierto" class="warn" @click="action(item,'declarar-desierto')">Desierto</button></footer></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="filters.page<=1" @click="load(filters.page-1)">Anterior</button><span>{{filters.page}} / {{lastPage}}</span><button :disabled="filters.page>=lastPage" @click="load(filters.page+1)">Siguiente</button></footer>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="modal wide" @submit.prevent="save"><header><div><small>Proceso de compra</small><h2>{{editing?'Editar':'Registrar'}} proceso</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Título *<input v-model.trim="form.titulo" maxlength="255"></label><label>Tipo<select v-model="form.tipo"><option value="m">Materiales</option><option value="a">Activos</option><option value="s">Servicios</option></select></label></div><label>Descripción<textarea v-model.trim="form.descripcion" rows="3"/></label><h3>Pedidos relacionados</h3><input v-model.trim="pedidoSearch" placeholder="Buscar pedido por código o glosa…"><div class="orders"><button v-for="order in availableOrders" :key="order.id" type="button" :class="{selected:form.pedidos_relacionados.includes(order.id)}" @click="toggleOrder(order.id)"><b>#{{order.id}}</b><span>{{order.informacion||'Sin glosa'}}</span><em>{{form.pedidos_relacionados.includes(order.id)?'✓ Seleccionado':'Seleccionar'}}</em></button></div><h3>Cronograma de etapas</h3><div class="stages"><header><span>Orden</span><span>Etapa</span><span>Inicio</span><span>Fin</span><span></span></header><article v-for="(stage,i) in form.etapas" :key="stage.id"><b>{{i+1}}</b><span>{{stage.nombre}}</span><input v-model="stage.fecha_inicio" type="date"><input v-model="stage.fecha_fin" type="date"><div><button type="button" @click="move(i,-1)">↑</button><button type="button" @click="move(i,1)">↓</button></div></article></div><footer><button type="button" class="clear" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar proceso'}}</button></footer></form></div>
<div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="modal wide"><header><div><small>Proceso #{{detail.id}}</small><h2>{{detail.nombre}}</h2><p>{{detail.descripcion}}</p></div><button @click="detail=null">×</button></header><section class="summary"><div><b>{{detail.estado_nombre}}</b><span>Estado</span></div><div><b>{{detail.etapa_nombre||'—'}}</b><span>Etapa</span></div><div><b>{{detail.postores_count}}</b><span>Postores</span></div><div><b>{{detail.pedidos?.length||0}}</b><span>Pedidos</span></div></section><h3>Pedidos relacionados</h3><div class="compact"><div v-for="order in detail.pedidos" :key="order.id"><b>#{{order.id}}</b><span>{{order.informacion}}</span></div></div><h3>Cronograma</h3><div class="compact"><div v-for="stage in detail.etapas" :key="stage.id"><b>{{stage.orden}}. {{stage.nombre}}</b><span>{{stage.fecha_inicio}} → {{stage.fecha_fin}}</span></div></div><h3>Seguimiento de validaciones</h3><div class="compact"><div v-for="entry in detail.seguimiento" :key="entry.id"><b>{{entry.proveedor||entry.usuario}} · {{entry.resultado}}</b><span>{{entry.fecha}}</span><p>{{entry.comentario||entry.comentario_logistica||entry.comentario_proveedor}}</p></div><p v-if="!detail.seguimiento?.length">Sin validaciones registradas.</p></div><footer class="actions"><button class="clear" @click="detail=null">Cerrar</button><button v-if="detail.puede_enviar_validacion" @click="action(detail,'enviar-validacion')">Enviar a validación</button><button v-if="detail.puede_avanzar" class="good-bg" @click="action(detail,'siguiente-etapa')">Siguiente etapa</button><button v-if="detail.puede_declarar_desierto" class="warn-bg" @click="action(detail,'declarar-desierto')">Declarar desierto</button></footer></section></div></div></template>
<style scoped>
