n-top:12px;display:flex;justify-content:center;align-items:center;gap:8px;font-size:.55rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.modal{width:min(100%,600px);max-height:92vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.modal.wide{width:min(100%,950px)}.modal>header{display:flex}.modal h2{margin:2px 0;font-size:1rem}.modal header p{margin:4px 0;color:#7d898f;font-size:.58rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.modal label{display:block;margin-bottom:10px;font-size:.56rem}.grid{display:grid;grid-template-columns:2fr 1fr;gap:8px}.modal h3{font-size:.64rem}.orders{max-height:150px;overflow:auto;margin:6px 0 14px}.orders button{width:100%;padding:8px;display:grid;grid-template-columns:60px 1fr 90px;border:0;border-bottom:1px solid #e8ecee;background:#fff;text-align:left;font-size:.54rem}.orders button.selected{background:#f9edf2}.orders em{color:var(--accent);font-style:normal}.stages>header,.stages>article{padding:7px;display:grid;grid-template-columns:40px 1fr 130px 130px 60px;align-items:center;gap:5px}.stages>header{color:#fff;background:#6b7580;font-size:.5rem}.stages>article{border-bottom:1px solid #e8ecee;font-size:.55rem}.stages article button{border:0;color:var(--accent);background:none}.modal footer{margin-top:14px;display:flex;justify-content:flex-end;gap:6px}.clear{color:#68757c!important;background:#edf1f3!important}.summary{margin:14px 0;display:grid;grid-template-columns:repeat(4,1fr);gap:7px}.summary div{padding:10px;text-align:center;border-radius:7px;background:#f8edf2}.summary b,.summary span{display:block;font-size:.55rem}.compact>div{padding:8px;display:flex;gap:10px;flex-wrap:wrap;border-bottom:1px solid #e8ecee;font-size:.55rem}.compact>div b{min-width:150px}.compact>div span{margin-left:auto}.compact>div p{width:100%;margin:0;color:#7d898f}.good-bg{background:#287153!important}.warn-bg{background:#a36a18!important}@media(max-width:950px){.table>header,.stages>header{display:none}.table>article,.stages>article{grid-template-columns:1fr}.filters{align-items:stretch;flex-direction:column}.hero{flex-wrap:wrap}.hero strong{margin-left:0}.summary{grid-template-columns:repeat(2,1fr)}}
</style>
